                # The 9 boundary on this row determines the ray direction.
                walls=[j for j in range(w) if grid[r][j]==9]
                if walls:
                    wall=min(walls,key=lambda j:abs(j-c))
                    step=1 if wall>c else -1
                    j=c+step
                    while j!=wall:
                        if grid[r][j]==3: break
                        g[r][j]=7
                        j+=step
                    g[r][c]=4
